# pretty names used by the format pill / devices view
FORMAT_NAMES = {
    ".mp3": "MP3", ".flac": "FLAC", ".ogg": "OGG", ".opus": "OPUS", ".m4a": "M4A",
    ".mp4": "M4A", ".aac": "AAC", ".wav": "WAV", ".wma": "WMA", ".aiff": "AIFF",
    ".aif": "AIFF", ".ape": "APE", ".wv": "WV", ".alac": "ALAC",
}
